<?php
namespace App\Http\Controllers\Admin\Finance;use App\Http\Controllers\Controller;use App\Models\DivisionTenderParty;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class DivisionTenderPartyController extends Controller{public function index(Request $r){$this->auth($r);return view('admin.finance.division-parties.index',['parties'=>DivisionTenderParty::where('division_id',$r->user()->id)->latest('serial_number')->paginate(10)]);}public function create(Request $r){$this->auth($r);return view('admin.finance.division-parties.form',['party'=>null,'next'=>((int)DivisionTenderParty::where('division_id',$r->user()->id)->max('serial_number'))+1]);}public function store(Request $r){$this->auth($r);$v=$r->validate(['data'=>['required','array'],'attachments'=>['nullable','array'],'attachments.*'=>['file','max:20480'],'party_status'=>['required']]);$files=collect($r->file('attachments',[]))->map(fn($f)=>$f->store('division-party-attachments','public'))->all();DivisionTenderParty::create(['division_id'=>$r->user()->id,'serial_number'=>((int)DivisionTenderParty::where('division_id',$r->user()->id)->max('serial_number'))+1,'data'=>$v['data'],'attachments'=>$files,'party_status'=>$v['party_status']]);return redirect()->route('division.parties.index')->with('status','Your data is submitted.');}public function edit(Request $r,DivisionTenderParty $party){$this->auth($r);abort_unless($party->division_id===$r->user()->id,403);return view('admin.finance.division-parties.form',['party'=>$party,'next'=>$party->serial_number]);}public function update(Request $r,DivisionTenderParty $party){$this->auth($r);abort_unless($party->division_id===$r->user()->id,403);$v=$r->validate(['data'=>['required','array'],'party_status'=>['required']]);$party->update(['data'=>$v['data'],'party_status'=>$v['party_status']]);return redirect()->route('division.parties.index')->with('status','Party updated successfully.');}public function destroy(Request $r,DivisionTenderParty $party){$this->auth($r);abort_unless($party->division_id===$r->user()->id,403);Storage::disk('public')->delete($party->attachments??[]);$party->delete();return back()->with('status','Party deleted successfully.');}private function auth(Request $r):void{abort_unless($r->user()->isDivision(),403);}}